/** Book shelf and chapter reader. GitHub actions reference the exact public Markdown file; no writes occur here. */
import {book} from './books-data.mjs';
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const base='https://github.com/adu-works/self-website';
const href=c=>`#/book/${book.id}/${c.id}`;
const paragraphs=list=>list.map(p=>`<p>${esc(p)}</p>`).join('');
const icon=type=>`<svg viewBox="0 0 24 24" width="21" height="21" fill="none" stroke="currentColor" stroke-width="1.7" aria-hidden="true"><path d="M14 3H5v18h8M14 3v6h6L14 3Z"/>${type==='view'?'<path d="M13 16c3-5 6-5 9 0-3 5-6 5-9 0Z"/><circle cx="17.5" cy="16" r="1"/>':'<path d="m13 20 1-4 6-6 3 3-6 6-4 1Z"/>'}</svg>`;
export function bookFeature(){return `<section class="book-feature"><div><span class="eyebrow">我的书籍 / 书稿示例</span><h2>把一个问题，写得更完整。</h2><p>从一篇文章往前走，把思考整理成有顺序的章节。</p></div><a class="text-link" href="#/books">进入书籍栏目 ↗</a></section>`}
export function booksView(back){return `<div class="page-head">${back('home')}<span class="eyebrow">BOOKS / 黄凌波</span><h1>书籍与长篇写作</h1><p>完整地讨论一个问题，也留出一起修订的空间。</p></div><section class="book-shelf"><div class="book-title-panel"><span class="eyebrow">示例书稿 / 01</span><h2>${book.title}</h2><p>${book.subtitle}</p><span>公开阅读 · 3 章示例</span></div><div class="book-shelf-copy"><span class="label">${book.status}</span><h2>从表达开始，慢慢搭建。</h2><p>这份书稿用来演示在线阅读、章节目录与 GitHub 协作。真实书名、书稿及出版信息之后由本人提供。</p><div class="hero-links"><a class="button" href="${href(book.chapters[0])}">开始阅读 ↗</a><a class="text-link" href="${base}/tree/main/prototype/books/independent-site" target="_blank" rel="noopener noreferrer">书稿仓库 ↗</a></div><ol>${book.chapters.map(c=>`<li><a href="${href(c)}">${c.id==='introduction'?'引言':c.id==='chapter1'?'第一章':'第二章'} · ${esc(c.title)}</a></li>`).join('')}</ol><p class="sample-note">这里展示自主写作的栏目形式，不代表已有正式出版物。示例书稿公开，付费资料不会通过此处暴露源码。</p></div></section>`}
export function chapterView(bookId,chapterId,back){if(bookId!==book.id)return null;const index=book.chapters.findIndex(c=>c.id===chapterId);if(index<0)return null;const c=book.chapters[index];const url=encodeURI(c.path);const toc=()=>c.sections.map(s=>`<a href="${href(c)}/${s.id}" data-section="${s.id}">${esc(s.title)}</a>`).join('');return `<div class="book-top">${back('books')}<a href="#/books">书籍 / ${book.title}</a><span class="label">示例书稿</span></div><div class="book-reader"><aside class="book-nav"><details open><summary>全书目录</summary><a class="book-directory-title" href="#/books">${book.title}</a>${book.chapters.map((x,i)=>`<a class="chapter-link" href="${href(x)}" ${x.id===c.id?'aria-current="page"':''}><span>${i===0?'引言':`第 ${i} 章`}</span>${esc(x.title)}</a>`).join('')}<p class="sample-note">公开书稿 · 3 章示例<br>非正式出版作品</p></details></aside><article class="book-body"><header class="chapter-heading" id="chapter-top"><div><span class="eyebrow">${index===0?'引言':`第 ${index} 章`} / ${book.chapters.length-1} 章正文</span><h1>${esc(c.title)}</h1></div><div class="chapter-actions"><a href="${base}/blob/main/${url}" target="_blank" rel="noopener noreferrer" title="在 GitHub 查看本章 Markdown 源文件">${icon('view')}<span>查看源文件</span></a><a href="${base}/edit/main/${url}" target="_blank" rel="noopener noreferrer" title="在 GitHub 编辑本章并提出修改">${icon('edit')}<span>编辑此章</span></a></div></header><p class="chapter-edit-note">编辑将在 GitHub 打开；读者可提交 PR，审核合并后再发布。</p><details class="mobile-chapter-toc"><summary>本章目录</summary>${toc()}</details><div class="chapter-intro">${paragraphs(c.intro)}</div>${c.sections.map(s=>`<section id="${s.id}"><h2>${esc(s.title)}</h2>${paragraphs(s.paragraphs)}</section>`).join('')}<nav class="chapter-pager" aria-label="章节翻页">${index>0?`<a href="${href(book.chapters[index-1])}"><small>← 上一章</small>${esc(book.chapters[index-1].title)}</a>`:'<span>这是全书起点</span>'}${index<book.chapters.length-1?`<a href="${href(book.chapters[index+1])}"><small>下一章 →</small>${esc(book.chapters[index+1].title)}</a>`:'<a href="#/books"><small>已到最后一章</small>返回书籍栏目 →</a>'}</nav></article><aside class="book-toc"><span class="eyebrow">本章目录</span>${toc()}<a class="text-link" href="${href(c)}/chapter-top" data-section="chapter-top">回到章节标题 ↑</a></aside></div>`}
